  GTypeFlags flags,
) {
  return withNativeString(typeName, (nativeTypeName) {
    return _gTypeRegisterStatic(
      parentType,
      nativeTypeName.cast<Utf8>(),
      info.handle,
      flags.value,
    );
  });
}
